mapper.select:
SELECT DesignId, LayoutCode, ChnlCode, LayoutImgCode, LayoutImgName, LayoutImgDesc,
       LayoutImgLink, LayoutImgHtml, LayoutImgWidth, LayoutImgHeight, NewwinYn,
       State, Remark, RegistId, RegistName, RegistDate, ChangeId, ChangeName, ChangeDate
FROM shopion.tStrLayoutImg


        AND DesignId = #{pDesignId}


        AND LayoutCode = #{pLayoutCode}


        AND ChnlCode = #{pChnlCode}


        AND LayoutImgCode = #{pLayoutImgCode}


ORDER BY LayoutImgCode

    LIMIT #{startNum}, #{countPerPage}

SELECT COUNT(*)
FROM shopion.tStrLayoutImg


        AND DesignId = #{pDesignId}


        AND LayoutCode = #{pLayoutCode}


        AND ChnlCode = #{pChnlCode}


        AND LayoutImgCode = #{pLayoutImgCode}

SELECT DesignId, LayoutCode, ChnlCode, LayoutImgCode, LayoutImgName, LayoutImgDesc,
       LayoutImgLink, LayoutImgHtml, LayoutImgWidth, LayoutImgHeight, NewwinYn,
       State, Remark, RegistId, RegistName, RegistDate, ChangeId, ChangeName, ChangeDate
FROM shopion.tStrLayoutImg
WHERE DesignId = #{pDesignId}
  AND LayoutCode = #{pLayoutCode}
  AND ChnlCode = #{pChnlCode}
  AND LayoutImgCode = #{pLayoutImgCode}
